110	// TestReceiptActionsFieldPresenceAndShape：凭据的 actions 缺失、为 null 或
111	// 写成非数组类型时，与空数组一样判整份文件损坏，错误带凭据位置、提案
112	// 编号、字段名与缺失/空值/类型不符原因。
113	func TestReceiptActionsFieldPresenceAndShape(t *testing.T) {
114		dir := t.TempDir()
115	
116		cases := []struct {
117			name    string
118			actions any // nil 表示删除字段
119			delete  bool
120			want    []string
121		}{
