123			{"missing field", nil, true, []string{`"gip-empty"`, `"actions"`, "is missing"}},
124			{"null", nil, false, []string{`"gip-empty"`, `"actions"`, "is null"}},
125			{"object", map[string]any{}, false, []string{`"gip-empty"`, `"actions"`, "has wrong type", "object"}},
126			{"string", "[]", false, []string{`"gip-empty"`, `"actions"`, "has wrong type", "string"}},
127			{"number", float64(0), false, []string{`"gip-empty"`, `"actions"`, "has wrong type", "number"}},
128			{"boolean", false, false, []string{`"gip-empty"`, `"actions"`, "has wrong type", "boolean"}},
129		}
130		for _, tc := range cases {
131			t.Run(tc.name, func(t *testing.T) {
132				path := filepath.Join(dir, "doc-"+strings.ReplaceAll(tc.name, " ", "-")+".json")
133				doc := emptyReceiptTaskDoc()
134				rcpt := doc["receipts"].([]any)[0].(map[string]any)
135				switch {
