171			{"number element", []any{float64(1)}},
172			{"string element", []any{"transfer:a:1"}},
173		} {
174			t.Run(tc.name, func(t *testing.T) {
175				path := filepath.Join(dir, "elem-"+strings.ReplaceAll(tc.name, " ", "-")+".json")
176				doc := emptyReceiptTaskDoc()
177				rcpt := doc["receipts"].([]any)[0].(map[string]any)
