181				s, err := Open(path)
182				if !errors.Is(err, ErrStateCorrupt) {
183					if s != nil {
184						s.Close()
185					}
186					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
187				}
188				if !strings.Contains(err.Error(), `"gip-empty"`) {
