269	// TestNormalReceiptsDoNotMaskEmptyReceipt：同一份文件里即使另有完全合法的
270	// 转账凭据（无论排在空凭据之前还是之后），即使本次只想查询正常提案，
271	// 空凭据都让整份文件打开失败。
272	func TestNormalReceiptsDoNotMaskEmptyReceipt(t *testing.T) {
273		dir := t.TempDir()
274	
275		// 先产生一份含合法凭据的状态：gip-good 转给 acct 10，余额 1000->990。
276		goodPath := filepath.Join(dir, "good.json")
277		store, err := InitTreasury(goodPath, 1000)
278		if err != nil {
279			t.Fatal(err)
280		}
281		mustRegister(t, store, "gip-good", 0, "transfer:acct:10")
282		if _, err := store.Execute("gip-good", 0); err != nil {
283			t.Fatal(err)
284		}
285		if err := store.Close(); err != nil {
286			t.Fatal(err)
287		}
288		goodRaw, err := os.ReadFile(goodPath)
289		if err != nil {
290			t.Fatal(err)
291		}
292	
293		emptyProposal := map[string]any{
294			"id": "gip-empty", "state": "executed",
295			"timelock_end": float64(0), "actions": []any{},
296		}
297		emptyReceipt := func(order float64) map[string]any {
298			return map[string]any{
299				"proposal_id": "gip-empty",
300				"executed_at": float64(0),
301				"order":       order,
302				"actions":     []any{},
303			}
304		}
305	
306		// 正常凭据在前、空凭据在后。
307		t.Run("empty receipt after normal receipt", func(t *testing.T) {
308			path := filepath.Join(dir, "after.json")
309			var doc map[string]any
310			if err := json.Unmarshal(goodRaw, &doc); err != nil {
311				t.Fatal(err)
312			}
313			doc["proposals"].(map[string]any)["gip-empty"] = emptyProposal
314			receipts := append(doc["receipts"].([]any), emptyReceipt(1))
315			doc["receipts"] = receipts
316			writeStateDoc(t, path, doc)
317			assertWholeFileCorrupt(t, path, "gip-empty", "gip-good")
318		})
319	
320		// 空凭据在前、正常凭据在后（合法凭据 order 改成 1）。
321		t.Run("empty receipt before normal receipt", func(t *testing.T) {
322			path := filepath.Join(dir, "before.json")
323			var doc map[string]any
324			if err := json.Unmarshal(goodRaw, &doc); err != nil {
325				t.Fatal(err)
326			}
327			doc["proposals"].(map[string]any)["gip-empty"] = emptyProposal
328			existing := doc["receipts"].([]any)[0].(map[string]any)
329			existing["order"] = float64(1)
330			doc["receipts"] = []any{emptyReceipt(0), existing}
331			writeStateDoc(t, path, doc)
332			assertWholeFileCorrupt(t, path, "gip-empty", "gip-good")
333		})
334	}
335	
336	// assertWholeFileCorrupt 断言含空凭据的文件整份打不开：即使查询正常提案
337	// 或正常凭据也没有任何部分成功结果，且原文件不被改写。
338	func assertWholeFileCorrupt(t *testing.T, path, emptyID, goodID string) {
339		t.Helper()
340		raw, err := os.ReadFile(path)
341		if err != nil {
342			t.Fatal(err)
343		}
344		s, err := Open(path)
345		if !errors.Is(err, ErrStateCorrupt) {
346			if s != nil {
347				s.Close()
348			}
349			t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
350		}
351		if !strings.Contains(err.Error(), `"`+emptyID+`"`) ||
352			!strings.Contains(err.Error(), "has no actions") {
353			t.Fatalf("error must name %s and explain empty actions: %v", emptyID, err)
354		}
355		// 打开失败意味着连正常提案/凭据也查不到：不存在能返回部分结果的句柄。
356		if _, oerr := Open(path); !errors.Is(oerr, ErrStateCorrupt) {
357			t.Fatalf("querying %s must not succeed on a file that also contains %s: %v",
358				goodID, emptyID, oerr)
359		}
360		if got, _ := os.ReadFile(path); string(got) != string(raw) {
361			t.Fatalf("corrupt file was modified")
362		}
363	}
364	
365	// TestEmptyReceiptSpottedOnAlreadyOpenStore：已经打开的资金库随后读到
366	// 空凭据内容时，每次操作都重新读取并按状态损坏失败，而不是沿用打开时
367	// 的内存视图返回旧余额/旧凭据。
368	func TestEmptyReceiptSpottedOnAlreadyOpenStore(t *testing.T) {
369		dir := t.TempDir()
370		path := filepath.Join(dir, "treasury.json")
371		store, err := InitTreasury(path, 100)
372		if err != nil {
373			t.Fatal(err)
374		}
375		// 无动作提案尚未执行：登记与查询正常。
376		if existed, err := store.Register("gip-empty", 0, nil); err != nil || existed {
377			t.Fatalf("register no-action proposal: existed=%v err=%v", existed, err)
378		}
379		record, ok, err := store.Proposal("gip-empty")
380		if err != nil || !ok || record.State != "passed" {
381			t.Fatalf("query before swap: %+v ok=%v err=%v", record, ok, err)
382		}
383	
384		// 文件在句柄存活期间被换成“executed + 空凭据”的损坏内容。
385		writeStateDoc(t, path, emptyReceiptTaskDoc())
386		corrupt, _ := os.ReadFile(path)
387	
388		for _, op := range []struct {
389			name string
390			run  func() error
391		}{
392			{"BalanceSnapshot", func() error { _, e := store.BalanceSnapshot(); return e }},
393			{"TreasuryBalance", func() error { _, e := store.TreasuryBalance(); return e }},
394			{"Proposal", func() error { _, _, e := store.Proposal("gip-empty"); return e }},
395			{"Proposals", func() error { _, e := store.Proposals(); return e }},
396			{"Receipt", func() error { _, _, e := store.Receipt("gip-empty"); return e }},
397			{"Receipts", func() error { _, e := store.Receipts(); return e }},
398		} {
399			if err := op.run(); !errors.Is(err, ErrStateCorrupt) {
400				t.Fatalf("%s after swap err=%v, want ErrStateCorrupt", op.name, err)
401			}
402		}
403		if rcpt, err := store.Execute("gip-empty", 0); !errors.Is(err, ErrStateCorrupt) || rcpt != nil {
404			t.Fatalf("Execute after swap rcpt=%+v err=%v, want nil + ErrStateCorrupt", rcpt, err)
405		}
406		if got, _ := os.ReadFile(path); string(got) != string(corrupt) {
407			t.Fatalf("corrupt file was modified by rejected operations")
408		}
409		store.Close()
410	}
411	
412	// TestNoActionUnexecutedProposalUsageUnchanged：无动作提案尚未执行时的
413	// 现有用法保持不变——登记/创建投票、正常查询、按既有规则投票计票都照常；
414	// 通过后执行继续以没有动作为由拒绝，状态、余额与凭据记录保持原样。
415	func TestNoActionUnexecutedProposalUsageUnchanged(t *testing.T) {
416		// 登记来源：可登记（含空切片与 nil 等价重试）、可查询，执行拒绝且不留痕。
417		store, path := openTempStore(t, 100)
418		defer store.Close()
419		if existed, err := store.Register("gip-nil", 0, nil); err != nil || existed {
420			t.Fatalf("register nil actions: existed=%v err=%v", existed, err)
421		}
422		if existed, err := store.Register("gip-nil", 0, []string{}); err != nil || !existed {
423			t.Fatalf("empty-slice retry: existed=%v err=%v", existed, err)
424		}
425		rec, ok, err := store.Proposal("gip-nil")
426		if err != nil || !ok || rec.State != "passed" || len(rec.Actions) != 0 {
427			t.Fatalf("query no-action proposal: %+v ok=%v err=%v", rec, ok, err)
428		}
429		if rcpt, eerr := store.Execute("gip-nil", 0); !errors.Is(eerr, ErrExecutionRejected) ||
430			!strings.Contains(eerr.Error(), "no actions") || rcpt != nil {
431			t.Fatalf("execute register no-action rcpt=%+v err=%v", rcpt, eerr)
432		}
433		if bal, _ := store.TreasuryBalance(); bal != 100 {
434			t.Fatalf("treasury changed: %d", bal)
435		}
436		if rs, _ := store.Receipts(); len(rs) != 0 {
437			t.Fatalf("receipt created for no-action rejection: %+v", rs)
438		}
439		rec, _, _ = store.Proposal("gip-nil")
440		if rec.State != "passed" {
441			t.Fatalf("state changed after rejected execute: %s", rec.State)
442		}
443	
444		// 投票来源：无动作也可创建、投票与计票（按既有规则通过），执行拒绝。
445		in := baseVoteInput("gip-vote-empty")
446		in.Actions = []string{}
447		mustCreateVote(t, store, in)
448		if _, err := store.CastVote("gip-vote-empty", "alice", true, 150); err != nil {
449			t.Fatal(err)
450		}
451		tally, err := store.TallyVote("gip-vote-empty", 200)
452		if err != nil || !tally.Passed {
453			t.Fatalf("tally=%+v err=%v", tally, err)
454		}
455		if rcpt, eerr := store.Execute("gip-vote-empty", 300); !errors.Is(eerr, ErrExecutionRejected) ||
456			!strings.Contains(eerr.Error(), "no actions") || rcpt != nil {
457			t.Fatalf("execute vote no-action rcpt=%+v err=%v", rcpt, eerr)
458		}
459		vp, ok, err := store.VoteProposal("gip-vote-empty")
460		if err != nil || !ok || vp.State != "passed" {
461			t.Fatalf("vote proposal state after rejected execute: %+v ok=%v err=%v", vp, ok, err)
462		}
463		// 再次计票返回首次结论，不转账。
464		again, err := store.TallyVote("gip-vote-empty", 201)
465		if err != nil || !again.Passed {
466			t.Fatalf("retally=%+v err=%v", again, err)
467		}
468		if bal, _ := store.TreasuryBalance(); bal != 100 {
469			t.Fatalf("treasury changed after no-action vote flow: %d", bal)
470		}
471	
472		// 重开：未执行的无动作提案（两种来源）仍是合法状态，查询不受影响。
473		store.Close()
474		reopened, err := Open(path)
475		if err != nil {
476			t.Fatalf("reopen: %v", err)
477		}
478		defer reopened.Close()
479		if rec, ok, _ := reopened.Proposal("gip-nil"); !ok || rec.State != "passed" {
480			t.Fatalf("register proposal after reopen: %+v ok=%v", rec, ok)
481		}
482		if vp, ok, _ := reopened.VoteProposal("gip-vote-empty"); !ok || vp.State != "passed" {
483			t.Fatalf("vote proposal after reopen: %+v ok=%v", vp, ok)
484		}
485		if bal, _ := reopened.TreasuryBalance(); bal != 100 {
486			t.Fatalf("treasury after reopen: %d", bal)
487		}
488		if rs, _ := reopened.Receipts(); len(rs) != 0 {
489			t.Fatalf("receipts after reopen: %+v", rs)
490		}
491	}
492	
493	// TestRealTransferReceiptStillReadsIncludingZeroTreasury：含真实转账动作的
494	// 合法凭据继续按已有规则读取；转账后资金库余额恰好为零也是有效结果，
495	// 重试仍返回首次凭据。
496	func TestRealTransferReceiptStillReadsIncludingZeroTreasury(t *testing.T) {
497		store, path := openTempStore(t, 100)
498		defer store.Close()
499		mustRegister(t, store, "gip-zero", 0, "transfer:acct:40", "transfer:acct:60")
500		first, err := store.Execute("gip-zero", 0)
501		if err != nil {
502			t.Fatalf("execute: %v", err)
503		}
504		if len(first.Actions) != 2 || first.Actions[1].Treasury.After != 0 {
505			t.Fatalf("unexpected receipt: %+v", first)
506		}
507		if bal, _ := store.TreasuryBalance(); bal != 0 {
508			t.Fatalf("treasury=%d, want 0", bal)
509		}
510		store.Close()
511	
512		reopened, err := Open(path)
513		if err != nil {
514			t.Fatalf("zero-treasury receipt must still read: %v", err)
515		}
516		defer reopened.Close()
517		if bal, _ := reopened.TreasuryBalance(); bal != 0 {
518			t.Fatalf("treasury after reopen=%d, want 0", bal)
519		}
520		if snap, err := reopened.BalanceSnapshot(); err != nil || snap.Treasury != 0 || snap.Balances["acct"] != 100 {
521			t.Fatalf("snapshot=%+v err=%v", snap, err)
522		}
523		again, err := reopened.Execute("gip-zero", 999)
524		if err != nil || again.Order != first.Order || again.ExecutedAt != first.ExecutedAt ||
525			len(again.Actions) != 2 {
526			t.Fatalf("retry receipt=%+v err=%v", again, err)
527		}
528	}
